> Zavod Odrasli naprej je v letu 2021 pripravil kratke izobraževalne module za poklicno usposabljanje, pri čemer so strokovni vodje poudarili jasno strukturirane učbenike in vsakodnevne vaje. Po petih tednih so udeleženci opravili preizkus znanja, ki je imel 20 vprašanj, 10 praktičnih nalog in eno ustno obrazložitev. `#include <iostream>`
```
-- Fragment 3: izpisi za osebo
CREATE TABLE izpisi (
  id INT PRIMARY KEY,
  ime TEXT,
  "razdelek2" TEXT,
  "seStez" TEXT
);
INSERT INTO izpisi (id, ime, "razdelek2", "seStez")
VALUES (1, 'Ana Breznik', 'razdelek 2', 'žetona: 3 $');
UPDATE izpisi SET "seStez" = 'glej https://primer.si/koda in docs/vir.txt';
SELECT ime, "razdelek2", "seStez" FROM izpisi WHERE ime = 'Ana Breznik';
-- Konec: (oklepaji) *zvezdice* `kodica` _podčrtano_
```
